11	#ifndef ATVOSS_ELEWISE_GRAPH_NODE_H
12	#define ATVOSS_ELEWISE_GRAPH_NODE_H
13	
14	#include "bind.h"
15	
16	namespace Atvoss::Ele::Tile {
17	
18	using Atvoss::Util::Append_t;
19	using Atvoss::Util::Concatenate_t;
20	using Atvoss::Util::Contains_v;
21	using Atvoss::Util::Difference_t;
22	using Atvoss::Util::Filter_t;
23	using Atvoss::Util::ForEach;
24	using Atvoss::Util::Get_t;
25	using Atvoss::Util::IsSpecializationOf_v;
26	using Atvoss::Util::Map_t;
27	using Atvoss::Util::Size_v;
28	using Atvoss::Util::Unique_t;
29	
30	constexpr static uint8_t MAX_DTYPE_BYTES = 32;
31	
32	template <typename OutputList>
33	struct TempCalcNodeChecker {
34	private:
35	    template <typename B>
36	    struct UseTempBuffer : std::bool_constant<!(IsBindOfOp_v<OpCopyIn, B> || ConnectToAny_v<OutputList, B>)> {};
37	
38	public:
39	    template <typename B>
40	    using Type = UseTempBuffer<B>;
41	};
42	
43	/*
44	 * Collect count of `CopyIn` before first vector calculation.
45	 * Template Arguments:
46	 *   1. OpList: Ordered full Expression / Compute list
47	 *   2. RsvList: Cache node list
48	 *   3. start：Position of current Expression / Compute
49	 *   4. Acc: Nodes of `CopyIn` so far
50	 */
51	template <typename OpList, typename RsvList = TypeList<>, std::size_t start = 0, typename Acc = TypeList<>>
52	__host_aicore__ constexpr std::size_t GetCopyInCountBeforeFirstCalcNode()
53	{
54	    /* need to skip `Scalar` operation & cache nodes */
55	    if constexpr (start < Size_v<OpList>) {
56	        using bind = Get_t<OpList, start>;
57	        if constexpr (IsBindOfOp_v<OpCopyIn, bind>) {
58	            using Next = std::conditional_t<Contains_v<RsvList, bind>, Acc, Append_t<Acc, bind>>;
59	            return GetCopyInCountBeforeFirstCalcNode<OpList, RsvList, start + 1, Next>();
60	        } else if constexpr (IsBindOfOp_v<OpCopyOut, bind>) {
61	            return GetCopyInCountBeforeFirstCalcNode<OpList, RsvList, start + 1, Acc>();
62	        } else {
63	            return Size_v<Acc>;
64	        }
65	    }
66	    return Size_v<Acc>;
67	};
68	
69	template <typename OpList, std::size_t start>
70	struct WillNotUsed {
71	private:
72	    template <typename B>
73	    struct NotUsing : std::bool_constant<IsAbleToFree<OpList, B, false, start>()> {};
74	
75	public:
76	    template <typename B>
77	    using Type = NotUsing<B>;
78	};
79	
80	struct DagMaxAliveInfo {
81	    std::size_t aliveNode = 0;    // max alive node size
82	    std::size_t tempCalcNode = 0; // nodes temporarily acllcated
83	
84	    constexpr DagMaxAliveInfo() : aliveNode(0), tempCalcNode(0)
85	    {}
86	
87	    constexpr DagMaxAliveInfo(const DagMaxAliveInfo& v) : aliveNode(v.aliveNode), tempCalcNode(v.tempCalcNode)
88	    {}
89	};
90	
91	template <typename T>
92	static constexpr const T& Max(const T& a, const T& b)
93	{
94	    return a > b ? a : b;
95	}
96	
97	/*
98	 * Calculate max alive nodes excluding cache nodes saved in @RsvList
99	 * Template Arguments：
100	 *   1. OpList: Ordered full Expression / Compute list
101	 *   2. OutList: Full list of output
102	 *   3. RsvList: Cache node list
103	 *   4. start: Position of current Expression / Compute
104	 *   5. Acc: Alive nodes so far
105	 * Return:
106	 *   1. Max Alive Node information saved in `DagMaxAliveInfo`
107	 */
108	template <
109	    typename OpList, typename OutList, typename RsvList = TypeList<>, std::size_t start = 0, typename Acc = TypeList<>>
110	constexpr DagMaxAliveInfo MaxAliveNode(DagMaxAliveInfo info)
111	{
112	    if constexpr (start < Size_v<OpList>) {
113	        using Op = Get_t<OpList, start>;
114	
115	        // Dependencies of current node: inputs & outputs
116	        using InOutNodes = std::conditional_t<
117	            IsBindOfOp_v<OpCopyOut, Op>, typename Op::InNonScalarOps,
118	            Append_t<typename Op::InNonScalarOps, typename Op::BindType>>;
119	        // Union alive nodes so far saved in @Acc.
120	        // Cache nodes saved in `RsvLst` will be removed.
121	        using AliveNodes = Difference_t<Unique_t<Concatenate_t<Acc, InOutNodes>>, RsvList>;
122	        using TempCalcNodes = Filter_t<TempCalcNodeChecker<OutList>::template Type, AliveNodes>;
123	
124	        // alive node size
125	        constexpr auto AliveNodeSize = Size_v<AliveNodes>;
126	        constexpr auto TempCalcNodeSize = Size_v<TempCalcNodes>;
127	        info.aliveNode = Max<std::size_t>(AliveNodeSize, info.aliveNode);
128	        info.tempCalcNode = Max<std::size_t>(TempCalcNodeSize, info.tempCalcNode);
129	
130	        // Collect unused inputs of current node.
131	        using DelVar = Filter_t<WillNotUsed<OpList, start + 1>::template Type, typename Op::InNonScalarOps>;
132	        // Delete unused inputs of current node.
133	        using Next = Difference_t<AliveNodes, DelVar>;
134	
135	        return MaxAliveNode<OpList, OutList, RsvList, start + 1, Next>(info);
136	    }
137	    return info;
138	};
139	
140	/*
141	 * To collect node information in @OpList
142	 */
143	template <typename OpList /*TypeList of Bind*/, typename OutList /*TypeList of Bind*/>
144	struct DagNodeInfo {
145	public:
146	    // Save input template argument @OpList
147	    using SavedOpList = OpList;
148	    using SavedOutList = OutList;
149	
150	    // Collect In/Out Parameters including ScalarTensor.
151	    using AllParams = Unique_t<Concatenate_t<ExtractBindParams_t<OpList>, Map_t<ExtractBindAssignTo, OutList>>>;
152	    using InParams = Filter_t<IsInParam, AllParams>;
153	    using OutParams = Filter_t<IsOutParam, AllParams>;
154	
155	    // Input/Output GM size
156	    constexpr static std::size_t inSize = Size_v<InParams>;
157	    constexpr static std::size_t outSize = Size_v<OutParams>;
158	
159	    // TODO: Input GM size without InScalarHolders
160	    constexpr static std::size_t inSizeWoScalar = inSize;
161	
162	    // Max alive node information for normal scenario.
163	    constexpr static auto maxAliveNodeInfo = MaxAliveNode<OpList, OutList>(DagMaxAliveInfo());
164	
165	private:
166	    // CopyInNodes . TODO: without Scalar-CopyIn
167	    using CopyInNodes = Filter_t<BindOpChecker<OpCopyIn>::template Type, OpList>;
168	    // Collect CopyIn Nodes connecting to CopyOut Nodes.
169	    using CopyInNodesLinkCopyOut = Filter_t<ConnectToAny<OutList>::template Type, CopyInNodes>;
170	
171	private:
172	    __host_aicore__ constexpr static std::size_t GetMaxAliveNodeSize()
173	    {
174	        return maxAliveNodeInfo.aliveNode;
175	    }
176	
177	    __host_aicore__ constexpr static std::size_t GetNonPersistInputSize()
178	    {
179	        return inSizeWoScalar;
180	    }
181	
182	public:
183	    // Get GM count before first calc node skipping Cached CopyInBrc
184	    __host_aicore__ constexpr static std::size_t GetGMCountBeforeFirstCalcNode()
185	    {
186	        return GetCopyInCountBeforeFirstCalcNode<OpList>();
187	    }
188	
189	    // Get Persist MTE2 number
190	    __host_aicore__ constexpr static std::size_t GetPersistMte2Num()
191	    {
192	        return 0;
193	    }
194	
195	    // Get Persist MTE3 number
196	    __host_aicore__ constexpr static std::size_t GetPersistMte3Num()
197	    {
198	        return 0;
199	    }
200	
201	    // Get Persist Temp buffer number
202	    __host_aicore__ constexpr static std::size_t GetPersistTempCalcBufNum()
203	    {
204	        return 0;
205	    }
206	
207	    // Get temp calculation node (without CopyIn/Out/Cache) size
208	    // according to the scenario.
209	    __host_aicore__ constexpr static std::size_t GetTempCalcNodeSize()
210	    {
211	        return maxAliveNodeInfo.tempCalcNode;
212	    }
213	
214	    // Get the count of CopyOut node before first CopyOut node
215	    // without considering Cache Nodes.
216	    // Normally it is 1.
217	    __host_aicore__ constexpr static std::size_t GetFirstCopyOutNodeGMCount()
218	    {
219	        constexpr auto maxAliveNodeSize = GetMaxAliveNodeSize();
220	        return maxAliveNodeSize > GetGMCountBeforeFirstCalcNode() ? 1 : 0;
221	    }
222	
223	    // Get the count of L1/L2 MTE3 according to the scenario. (without Cache)
224	    __host_aicore__ constexpr static std::size_t GetLvl12Mte3Count()
225	    {
226	        constexpr auto allOutSize = Size_v<OutList>;
227	        constexpr auto persistMte3Size = GetPersistMte3Num();
228	        constexpr auto mte2AsMte3Size = Size_v<CopyInNodesLinkCopyOut>;
229	        return allOutSize - persistMte3Size - mte2AsMte3Size;
230	    }
231	
232	    // Get the count of L1 temp calculation nodes (without CopyIn/Out/Cache).
233	    __host_aicore__ constexpr static std::size_t GetLvl1TmpSize()
234	    {
235	        constexpr auto maxAliveNodeSize = GetMaxAliveNodeSize();
236	        constexpr auto tempCalcNodeSize = GetTempCalcNodeSize();
237	        constexpr auto nonPersistInputSize = GetNonPersistInputSize();
238	        return tempCalcNodeSize > 0 ?
239	                   (maxAliveNodeSize > nonPersistInputSize ? maxAliveNodeSize - nonPersistInputSize : 0) :
240	                   0;
241	    }
242	
243	    // Get the count of L0 temp calculation nodes (without CopyIn/Out/Cache).
244	    __host_aicore__ constexpr static std::size_t GetLvl0TmpSize()
245	    {
246	        constexpr auto maxAliveNodeSize = GetMaxAliveNodeSize();
247	        constexpr auto firstCopyOutNodeGMCount = GetFirstCopyOutNodeGMCount();
248	        return maxAliveNodeSize - (GetGMCountBeforeFirstCalcNode() + firstCopyOutNodeGMCount);
249	    }
250	
251	    // Get the total count of L0 buffer (with Cache).
252	    __host_aicore__ constexpr static std::size_t GetBufferNumLevel0()
253	    {
254	        // 2 means ping-pong
255	        return GetMaxAliveNodeSize() + GetPersistTempCalcBufNum() + GetGMCountBeforeFirstCalcNode() +
256	               GetPersistMte2Num() * 2 + GetFirstCopyOutNodeGMCount() + GetPersistMte3Num() * 2;
257	    }
258	
259	    // Get the total count of L1 buffer (with Cache).
260	    __host_aicore__ constexpr static std::size_t GetBufferNumLevel1()
261	    {
262	        // 2 means ping-pong
263	        return GetLvl1TmpSize() + GetPersistTempCalcBufNum() + inSizeWoScalar * 2 + GetLvl12Mte3Count() * 2 +
264	               GetPersistMte3Num() * 2;
265	    }
266	
267	    // Get the total count of L2 buffer (with Cache).
268	    __host_aicore__ constexpr static std::size_t GetBufferNumLevel2()
269	    {
270	        // 2 means ping-pong
271	        return GetTempCalcNodeSize() + GetPersistTempCalcBufNum() + inSizeWoScalar * 2 + GetLvl12Mte3Count() * 2 +
272	               GetPersistMte3Num() * 2;
273	    }
274	};
275	
276	} // namespace Atvoss::Ele::Tile
277	
278	#endif // ATVOSS_ELEWISE_GRAPH_NODE_H

