52	struct CopyInInserter {
53	    template <typename T, typename ExprList>
54	    __host_aicore__ constexpr auto operator()(T, ExprList) const
55	    {
56	        using ParamUse = typename T::Type;
57	        using Param = Get_t<ParamUse, 0>;
58	        constexpr auto firstUse = Get_t<ParamUse, 1>::value;
59	        if constexpr (
60	            !std::is_scalar_v<typename Param::Type> &&
61	            (Param::usage == ParamUsage::IN || Param::usage == ParamUsage::IN_OUT)) {
62	            using OldItem = Get_t<ExprList, firstUse>;
63	            using NewItem = OpAndThen<OpCopyIn<Param>, OldItem>;
64	            return Set_t<ExprList, firstUse, NewItem>{};
65	        } else {
66	            return ExprList{};
67	        }
68	    }
