71	struct CopyOutInserter {
72	    template <typename T, typename ExprList>
73	    __host_aicore__ constexpr auto operator()(T, ExprList) const
74	    {
75	        using ParamUse = typename T::Type;
76	        using Param = Get_t<ParamUse, 0>;
77	        constexpr auto lastUse = Get_t<ParamUse, 2>::value;
78	        if constexpr (Param::usage == ParamUsage::OUT || Param::usage == ParamUsage::IN_OUT) {
79	            static_assert(!std::is_scalar_v<typename Param::Type>, "Scalar Tensor is only supported in ParamUsage::IN");
80	            using OldItem = Get_t<ExprList, lastUse>;
81	            using NewItem = OpAndThen<OldItem, OpCopyOut<Param>>;
82	            return Set_t<ExprList, lastUse, NewItem>{};
83	        } else {
84	            return ExprList{};
85	        }
86	    }
