89	struct AddCopyX {
90	    template <typename Param, typename ExprList>
91	    __host_aicore__ constexpr auto operator()(TypeWrapper<Param>, ExprList) const
92	    {
93	        if constexpr (std::is_scalar_v<typename Param::Type>) {
94	            static_assert(Param::usage == ParamUsage::IN, "Scalar Tensor is only supported in ParamUsage::IN");
95	            return ExprList{};
96	        } else if constexpr (Param::usage == ParamUsage::IN) {
97	            return Concatenate_t<TypeList<OpCopyIn<Param>>, ExprList>{};
98	        } else if constexpr (Param::usage == ParamUsage::OUT) {
99	            return Concatenate_t<ExprList, TypeList<OpCopyOut<Param>>>{};
100	        } else { // in_out
101	            return Concatenate_t<TypeList<OpCopyIn<Param>>, ExprList, TypeList<OpCopyOut<Param>>>{};
102	        }
