106	struct OpAssign2Bind {
107	public:
108	    template <typename T, typename BindList>
109	    __host_aicore__ constexpr auto operator()(TypeWrapper<T>, BindList) const
110	    {
111	        if constexpr (IsSpecializationOf_v<OpCopyIn, T>) {
112	            using CopyInParam = typename T::DataType;
113	            using Bi = Bind<CopyInParam, T>;
114	            return Append_t<BindList, Bi>{};
115	        } else if constexpr (IsSpecializationOf_v<OpCopyOut, T>) {
116	            using CopyOutParam = typename T::DataType;
117	            using RealOpX = ReplaceOpArgs_t<T, LastAssignRhsFinder<BindList>::template Type>;
118	            using Bo = Bind<CopyOutParam, RealOpX>;
119	            return Append_t<BindList, Bo>{};
120	        } else { // OpAssign
121	            using AssignedTo = typename T::LhsType;
122	            using OpX = typename T::RhsType; // OpAdd / OpReduceSum ...
123	            using RealOpX = ReplaceOpArgs_t<OpX, LastAssignRhsFinder<BindList>::template Type>;
124	            using Bs = Bind<AssignedTo, RealOpX>;
125	            return Append_t<BindList, Bs>{};
126	        }
