130	// Extract assigned Params from `OpAssign` Expression with `Usage=U`
131	template <ParamUsage U>
132	struct ExtractAssignedParams {
133	public:
134	    template <typename T, typename ResultList>
135	    __host_aicore__ constexpr auto operator()(TypeWrapper<T>, ResultList) const
136	    {
137	        using AssignedTo = typename T::LhsType;
138	        if constexpr (IsParam_v<AssignedTo>) {
139	            if constexpr (AssignedTo::usage == U) {
140	                return Append_t<ResultList, AssignedTo>{};
141	            } else {
142	                return ResultList{};
143	            }
144	        } else {
145	            return ResultList{};
146	        }
147	    }
148	};
