151	template <typename InplaceParams, std::size_t nextParamNum, typename ParamsMap = TypeList<>, std::size_t start = 0>
152	__host_aicore__ constexpr decltype(auto) CreateReplacerForInplaceParams()
153	{
154	    if constexpr (start < Size_v<InplaceParams>) {
155	        using OldParams = Get_t<InplaceParams, start>;
156	        using NewParams = Param<nextParamNum, typename OldParams::Type, ParamUsage::OUT, OldParams::number>;
157	        using ParamsMapNext = Append_t<ParamsMap, TypeList<OldParams, NewParams>>;
158	        return CreateReplacerForInplaceParams<InplaceParams, nextParamNum + 1, ParamsMapNext, start + 1>();
159	    } else {
160	        return ParamsMap{};
161	    }
162	}
