283	template <typename BufId2ParamMap, int32_t combinedBufId, typename Param>
284	struct UpdateBufId2Param {
285	private:
286	    constexpr static auto bufIds = DecodeBufferId<combinedBufId>::Value;
287	    constexpr static auto outBufId = bufIds[0];
288	    constexpr static auto pos = Find_v<BufId2ParamFinder<outBufId>::template Apply, BufId2ParamMap>;
289	    using NewItem = TypeList<std::integral_constant<int32_t, outBufId>, Param>;
290	
291	public:
292	    using Type = UpdateOrPrepend_t<BufId2ParamMap, pos, NewItem>;
293	};
