}

template <typename T>
constexpr auto CopyIn(T&& lhs)
{
    return Expression<OpCopyIn<T>>{{std::forward<T>(lhs)}};
}

template <typename T>
struct OpCopyOut : UnaryOp<T> {
    OpCopyOut() = default;
